create policy assigned_washer_order_read on public.orders for select to authenticated using (assigned_washer = auth.uid() and public.is_active_washer(auth.uid())); create policy assigned_washer_order_update on public.orders for update to authenticated using (assigned_washer = auth.uid() and public.is_active_washer(auth.uid())) with check (assigned_washer = auth.uid() and public.is_active_washer(auth.uid())); create or replace function guard_washer_order_updates() returns trigger language plpgsql security definer set search_path = public as $$ begin if public.has_role(auth.uid(),'admin') then return new; end if; if public.is_active_washer(auth.uid()) and old.assigned_washer = auth.uid() then if new.customer_id is distinct from old.customer_id or new.customer_name is distinct from old.customer_name or new.phone is distinct from old.phone or new.email is distinct from old.email or new.pickup_area is distinct from old.pickup_area or new.pickup_address is distinct from old.pickup_address or new.pickup_date is distinct from old.pickup_date or new.pickup_window is distinct from old.pickup_window or new.quote_amount is distinct from old.quote_amount or new.payment_status is distinct from old.payment_status or new.assigned_washer is distinct from old.assigned_washer or new.admin_notes is distinct from old.admin_notes or new.reference is distinct from old.reference then raise exception 'Washers may only update laundry progress.'; end if; if new.status not in ('in_progress','ready_for_review','ready_for_delivery') then raise exception 'Invalid washer status update.'; end if; return new; end if; raise exception 'Not allowed to update this order.'; end $$; drop trigger if exists guard_washer_order_updates on public.orders; create trigger guard_washer_order_updates before update on public.orders for each row execute function guard_washer_order_updates();